import type { Metadata } from "next";
import "./globals.css";

const themeScript = `(function(){try{var t=localStorage.getItem("icover-theme");if(t!=="light"&&t!=="dark")t=matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light";var e=document.documentElement;e.setAttribute("data-theme",t);e.style.colorScheme=t}catch(e){}})();`;

export const metadata: Metadata = {
  title: "iCover Studio",
  description: "Create your own gradient and Essentials-style playlist covers.",
};

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="en" data-theme="light" suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: themeScript }} />
      </head>
      <body>{children}</body>
    </html>
  );
}
